INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (445, 1, '-c 0', '`tune2fs -c 0` 처럼 최대 마운트 횟수를 0 이나 -1 로 두면 어떻게 될까요?', '횟수를 무시해요.', NULL, NULL, '[]', 'choice', '["마운트할 때마다 점검한다", "마운트가 거부된다", "마운트 횟수를 따지지 않는다", "점검 간격이 하루로 바뀐다"]', 2, 'tune2fs 문서는 max-mount-counts 가 0 이나 -1 이면 파일시스템이 마운트된 횟수를 무시한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 2, '-i 0', '`tune2fs -i 0` 은 무엇을 할까요?', '시간 기준이에요.', NULL, NULL, '[]', 'choice', '["마운트 횟수 기준 점검을 끈다", "시간 기준 점검을 끈다", "점검을 매 부팅마다 하게 한다", "저널 점검만 끈다"]', 1, '문서는 -i 가 두 점검 사이의 최대 시간을 정하며 0 이면 시간에 따른 점검을 끈다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 3, 'remount-ro', '`tune2fs -e remount-ro` 는 오류가 감지되면 어떻게 할까요?', '읽기 전용이에요.', NULL, NULL, '[]', 'choice', '["읽기 전용으로 다시 마운트한다", "정상 실행을 계속한다", "커널 패닉을 일으킨다", "장치를 자동으로 언마운트한다"]', 0, '문서는 -e 값으로 continue(정상 실행 계속), remount-ro(읽기 전용 재마운트), panic(커널 패닉)을 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 4, 'panic', '`tune2fs -e panic` 은 오류가 감지되면 어떻게 할까요?', '가장 강한 반응이에요.', NULL, NULL, '[]', 'choice', '["읽기 전용으로 다시 마운트한다", "오류를 무시하고 계속한다", "파일시스템을 삭제한다", "커널 패닉을 일으킨다"]', 3, '문서는 -e panic 이 오류 감지 시 커널 패닉을 일으킨다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 5, '-l 옵션', '`tune2fs -l` 은 무엇을 할까요?', '목록이에요.', NULL, NULL, '[]', 'choice', '["저널 내용을 출력한다", "파일 목록을 출력한다", "슈퍼블록의 내용을 출력한다", "배드 블록 목록을 출력한다"]', 2, '문서는 -l 이 파일시스템 슈퍼블록의 내용을 나열한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 6, '-r 옵션', '`tune2fs -r` 은 무엇을 정할까요?', '개수예요.', NULL, NULL, '[]', 'choice', '["예약할 블록의 비율", "예약할 블록의 개수", "예약 블록을 쓸 사용자", "예약 블록을 쓸 그룹"]', 1, '문서는 -r 이 예약 블록의 개수를 정하고 -m 이 비율을 정하며, -u·-g 가 예약 블록을 쓸 사용자·그룹을 정한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 7, 'has_journal', '`tune2fs -O has_journal` 은 무엇과 같을까요?', '저널을 추가해요.', NULL, NULL, '[]', 'choice', '["-j 옵션", "-c 옵션", "-e 옵션", "-L 옵션"]', 0, '문서는 has_journal 기능을 설정하는 것이 -j 옵션(ext3 저널 추가)을 쓰는 것과 같다고 설명합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 8, '-o 옵션', '`tune2fs -o` 는 무엇을 설정하거나 지울까요?', '기본값이에요.', NULL, NULL, '[]', 'choice', '["커널 부트 명령행 옵션", "/etc/fstab 의 마운트 옵션", "장치 큐의 동작 옵션", "저장된 기본 마운트 옵션"]', 3, '문서는 -o 가 파일시스템에 저장된 기본 마운트 옵션을 설정하거나 지운다고 설명합니다. -E mount_opts 도 기본 마운트 옵션을 정합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 9, '외부 저널 제거', '정상 언마운트되지 않은 파일시스템에서 **외부 저널을 제거** 하면 어떻게 될까요?', '경고가 있어요.', NULL, NULL, '[]', 'choice', '["저널이 자동으로 내부로 옮겨진다", "아무 영향이 전혀 없다", "심각한 데이터 손실이 생길 수 있다", "다음 마운트 때 저널이 복구된다"]', 2, '문서는 정상 언마운트되지 않은 파일시스템에서 외부 저널을 제거하면 심각한 데이터 손실과 파일시스템 손상이 생길 수 있다고 경고합니다.', NULL, NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 10, '오류 동작', '오류 감지 시 **커널 동작** 을 정하는 옵션입니다. 빈칸을 채우세요.', 'errors 의 e 예요.', NULL, NULL, '[]', 'fill', '["-e", "-c", "-i", "-O"]', NULL, '-e 는 오류 감지 시 동작(continue·remount-ro·panic)을 정합니다.', '[0]', 'tune2fs {0} remount-ro /dev/sdb1', NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 11, '볼륨 레이블', '볼륨 **레이블** 을 정하는 옵션입니다. 빈칸을 채우세요.', 'label 의 L 이에요.', NULL, NULL, '[]', 'fill', '["-L", "-U", "-l", "-m"]', NULL, '-L 은 볼륨 레이블을 정합니다. 소문자 -l 은 슈퍼블록 출력, -U 는 UUID 입니다.', '[0]', 'tune2fs {0} data /dev/sdb1', NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]'),
  (445, 12, '예약 블록 조정', '예약 블록 설정을 바꾸는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '확인 → 변경 → 사용자 → 재확인이에요.', NULL, NULL, '[]', 'order', '["`tune2fs -l` 로 현재 슈퍼블록 값을 확인한다", "`-m` 이나 `-r` 로 예약 블록을 바꾼다", "`-u`·`-g` 로 예약 블록을 쓸 사용자·그룹을 정한다", "`tune2fs -l` 로 바뀐 값을 다시 확인한다"]', NULL, '문서의 -l·-m·-r·-u·-g 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "tune2fs(8) man page", "url": "https://man7.org/linux/man-pages/man8/tune2fs.8.html"}]');
